        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'batch_lookup') {
    const err = new Error('Unknown tool: ' + name);
    err.code = -32601;
    throw err;
  }

  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
