    const err = new Error('Invalid arguments: unexpected keys ' + Object.keys(extra).join(', '));
    err.code = -32602;
    throw err;
  }

  if (!Array.isArray(ids)) {
    const err = new Error('Invalid arguments: ids must be an array');
    err.code = -32602;
    throw err;
  }
  if (ids.length === 0) {
    const err = new Error('Invalid arguments: ids must be a non-empty array');
    err.code = -32602;
    throw err;
  }
  for (const id of ids) {
    if (typeof id !== 'string') {
      const err = new Error('Invalid arguments: every id must be a string');
      err.code = -32602;
      throw err;
    }
  }

  const results = ids.map((id) => {
